class Solution {
    public boolean checkValid(int[][] matrix){
        int n=matrix.length;
        for(int i=0;i<n;i++){
            boolean[] row=new boolean[n+1],column=new boolean[n+1];
            for(int j=0;j<n;j++){
                int a=matrix[i][j],b=matrix[j][i];
                if(a<1||a>n||row[a]||b<1||b>n||column[b])return false;
                row[a]=true;
                column[b]=true;
            }
        }
        return true;
    }
}

code.kotlin:
class Solution {
    fun checkValid(matrix:Array<IntArray>):Boolean{
        val n=matrix.size;
        for(i in 0 until n){
            val row=BooleanArray(n+1);
            val column=BooleanArray(n+1);
            for(j in 0 until n){
                val a=matrix[i][j];
                val b=matrix[j][i];
                if(a !in 1..n||row[a]||b !in 1..n||column[b])return false;
                row[a]=true;
                column[b]=true
            }
        };
        return true
    }
}

